params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
$deleted=@();$skipped=@()
function Del([string]$b,[string]$expected,[scriptblock]$guard){
 $line=(git -C $repo ls-remote origin ("refs/heads/"+$b))
 if(-not $line){$script:skipped += [pscustomobject]@{branch=$b;reason='absent'};return}
 $actual=($line -split '\s+')[0]
 if($actual -ne $expected){throw "tip changed $b $actual"}
 & $guard
 git -C $repo push origin --delete $b
 if($LASTEXITCODE -ne 0){throw "delete failed $b"}
 $script:deleted += $b
}
Del 'agent/bridge-uia-native-20260929' 'e52328aea7a2cfa26a63a35e07003c736c9c571a' {
 $w=git -C $repo show 'origin/main:heaven-bridge/worker.py'
 $u=git -C $repo show 'origin/main:heaven-bridge/uia.ps1'
 $r=git -C $repo show 'origin/main:heaven-bridge/README.md'
 if(($w -notmatch '"uia_tree"') -or ($w -notmatch '"uia_set_value"') -or ($u -notmatch 'UIAutomationClient') -or ($r -notmatch 'Worker v4')){throw 'landed UIA proof failed'}
}
Del 'agent-bridge' '30fcf1d6a4946aaa8f760ab9b5141453b6b87e69' {
 $w=git -C $repo show 'origin/main:heaven-bridge/worker.py'
 $r=git -C $repo show 'origin/main:heaven-bridge/README.md'
 if(($w -notmatch 'chatgpt-heaven-bridge-v2') -or ($r -notmatch 'Worker v4')){throw 'canonical bridge proof failed'}
}
Del 'agent/control-test-narrow-test-scope-only-build-a-r-20260928133350-vrokm' 'b8f9424e274644ff5e76590e7dd44b05fe7c01a6' {
 foreach($p in @('_AGENT_CONTEXT/EVIDENCE/UPDATER_DISPOSABLE_HELPER_20260928.md','scripts/Test-UpdaterDisposable.Tests.ps1','scripts/Test-UpdaterDisposable.ps1')){
   git -C $repo cat-file -e ("origin/main:"+$p)
   if($LASTEXITCODE -ne 0){throw "main missing merged harness $p"}
 }
}
git -C $repo fetch origin --prune
[pscustomobject]@{deleted=$deleted;skipped=$skipped;main=(git -C $repo rev-parse origin/main).Trim()}|ConvertTo-Json -Depth 5 -Compress
